"""Softmax over the feature (last) axis of a 2-D input."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': '23_Softmax',
    'batch_size': 1024,
    'dim': 32768,
}


def create_inputs(dtype=jnp.float32):
    key = jax.random.key(0)
    x = jax.random.uniform(
        key, (CONFIG['batch_size'], CONFIG['dim']), dtype=dtype
    )
    return (x,)


def workload(x):
    # torch.softmax(x, dim=1): numerically stable softmax along the last axis.
    x_max = jnp.max(x, axis=-1, keepdims=True)
    e = jnp.exp(x - x_max)
    return e / jnp.sum(e, axis=-1, keepdims=True)

"""Exact (erf) GELU activation over a 2-D tensor."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': '26_GELU_',
    'batch_size': 4096,
    'dim': 16384,
}


def create_inputs(dtype=jnp.float32):
    key = jax.random.key(0)
    x = jax.random.uniform(key, (CONFIG['batch_size'], CONFIG['dim']), dtype)
    return (x,)


def workload(x):
    # torch.nn.functional.gelu default is the exact erf formulation.
    return jax.nn.gelu(x, approximate=False)

"""L2 normalization along dim=1: y = x / ||x||_2 (sum-of-squares reduce, sqrt, divide)."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': '39_L2Norm_',
    'batch_size': 2048,
    'dim': 16384,
}


def create_inputs(dtype=jnp.float32):
    key = jax.random.key(0)
    x = jax.random.uniform(key, (CONFIG['batch_size'], CONFIG['dim']), dtype)
    return (x,)


def workload(x):
    sq = jnp.sum(x * x, axis=1, keepdims=True)
    norm = jnp.sqrt(sq)
    return x / norm

